import{_ as t,a0 as o,w as d,s as r,ao as p,I as i,x as s,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"使用 GNU Parallel 提高 Linux 命令行执行效率 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GNU Parallel 提高 Linux 命令行执行效率 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GNU Parallel 提高 Linux 命令行执行效率 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GNU Parallel 提高 Linux 命令行执行效率 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180510 Get more done at the Linux command line with GNU Parallel","title":"使用 GNU Parallel 提高 Linux 命令行执行效率","tag":"201806","desc":""},"relativePath":"201806/20180510 Get more done at the Linux command line with GNU Parallel.md","filePath":"[post].md"}'),c={name:"201806/20180510 Get more done at the Linux command line with GNU Parallel.md"};function h(g,a,u,k,b,f){const l=o("Link");return d(),r("div",null,[a[23]||(a[23]=p('<h1 id="使用-gnu-parallel-提高-linux-命令行执行效率" tabindex="-1">使用 GNU Parallel 提高 Linux 命令行执行效率 <a class="header-anchor" href="#使用-gnu-parallel-提高-linux-命令行执行效率" aria-label="Permalink to “使用 GNU Parallel 提高 Linux 命令行执行效率”">​</a></h1><blockquote><p>将您的计算机变成一个多任务的动力室。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/rh_003499_01_linux11x_cc.png?itok=XMDOouJR" alt=""></p><p>你是否有过这种感觉，你的主机运行速度没有预期的那么快？我也曾经有过这种感觉，直到我发现了 GNU Parallel。</p><p>GNU Parallel 是一个 shell 工具，可以并行执行任务。它可以解析多种输入，让你可以同时在多份数据上运行脚本或命令。你终于可以使用全部的 CPU 了！</p><p>如果你用过 <code>xargs</code>，上手 Parallel 几乎没有难度。如果没有用过，这篇教程会告诉你如何使用，同时给出一些其它的用例。</p><h3 id="安装-gnu-parallel" tabindex="-1">安装 GNU Parallel <a class="header-anchor" href="#安装-gnu-parallel" aria-label="Permalink to “安装 GNU Parallel”">​</a></h3><p>GNU Parallel 很可能没有预装在你的 Linux 或 BSD 主机上，你可以从软件源中安装。以 Fedora 为例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install parallel</span></span></code></pre></div><p>对于 NetBSD：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pkg_add parallel</span></span></code></pre></div>',11)),i("p",null,[a[1]||(a[1]=s("如果各种方式都不成功，请参考",-1)),e(l,{href:"https://www.gnu.org/software/parallel"},{default:n(()=>[...a[0]||(a[0]=[s("项目主页",-1)])]),_:1}),a[2]||(a[2]=s("。",-1))]),a[24]||(a[24]=p(`<h3 id="从串行到并行" tabindex="-1">从串行到并行 <a class="header-anchor" href="#从串行到并行" aria-label="Permalink to “从串行到并行”">​</a></h3><p>正如其名称所示，Parallel 的强大之处是以并行方式执行任务；而我们中不少人平时仍然以串行方式运行任务。</p><p>当你对多个对象执行某个命令时，你实际上创建了一个任务队列。一部分对象可以被命令处理，剩余的对象需要等待，直到命令处理它们。这种方式是低效的。只要数据够多，总会形成任务队列；但与其只使用一个任务队列，为何不使用多个更小规模的任务队列呢？</p><p>假设你有一个图片目录，你希望将目录中的图片从 JEEG 格式转换为 PNG 格式。有多种方法可以完成这个任务。可以手动用 GIMP 打开每个图片，输出成新格式，但这基本是最差的选择，费时费力。</p><p>上述方法有一个漂亮且简洁的变种，即基于 shell 的方案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ convert 001.jpeg 001.png</span></span>
<span class="line"><span>$ convert 002.jpeg 002.png</span></span>
<span class="line"><span>$ convert 003.jpeg 003.png</span></span>
<span class="line"><span>... 略 ...</span></span></code></pre></div><p>对于初学者而言，这是一个不小的转变，而且看起来是个不小的改进。不再需要图像界面和不断的鼠标点击，但仍然是费力的。</p><p>进一步改进：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for i in *jpeg; do convert $i $i.png ; done</span></span></code></pre></div><p>至少，这一步设置好任务执行，让你节省时间去做更有价值的事情。但问题来了，这仍然是串行操作；一张图片转换完成后，队列中的下一张进行转换，依此类推直到全部完成。</p><p>使用 Parallel:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name &quot;*jpeg&quot; | parallel -I% --max-args 1 convert % %.png</span></span></code></pre></div><p>这是两条命令的组合：<code>find</code> 命令，用于收集需要操作的对象；<code>parallel</code> 命令，用于对象排序并确保每个对象按需处理。</p><ul><li><code>find . -name &quot;*jpeg&quot;</code> 查找当前目录下以 <code>jpeg</code> 结尾的所有文件。</li><li><code>parallel</code> 调用 GNU Parallel。</li><li><code>-I%</code> 创建了一个占位符 <code>%</code>，代表 <code>find</code> 传递给 Parallel 的内容。如果不使用占位符，你需要对 <code>find</code> 命令的每一个结果手动编写一个命令，而这恰恰是你想要避免的。</li><li><code>--max-args 1</code> 给出 Parallel 从队列获取新对象的速率限制。考虑到 Parallel 运行的命令只需要一个文件输入，这里将速率限制设置为 1。假如你需要执行更复杂的命令，需要两个文件输入（例如 <code>cat 001.txt 002.txt &gt; new.txt</code>），你需要将速率限制设置为 2。</li><li><code>convert % %.png</code> 是你希望 Parallel 执行的命令。</li></ul><p>组合命令的执行效果如下：<code>find</code> 命令收集所有相关的文件信息并传递给 <code>parallel</code>，后者（使用当前参数）启动一个任务，（无需等待任务完成）立即获取参数行中的下一个参数（LCTT 译注：管道输出的每一行对应 <code>parallel</code> 的一个参数，所有参数构成参数行）；只要你的主机没有瘫痪，Parallel 会不断做这样的操作。旧任务完成后，Parallel 会为分配新任务，直到所有数据都处理完成。不使用 Parallel 完成任务大约需要 10 分钟，使用后仅需 3 至 5 分钟。</p><h3 id="多个输入" tabindex="-1">多个输入 <a class="header-anchor" href="#多个输入" aria-label="Permalink to “多个输入”">​</a></h3><p>只要你熟悉 <code>find</code> 和 <code>xargs</code> （整体被称为 GNU 查找工具，或 <code>findutils</code>），<code>find</code> 命令是一个完美的 Parallel 数据提供者。它提供了灵活的接口，大多数 Linux 用户已经很习惯使用，即使对于初学者也很容易学习。</p><p><code>find</code> 命令十分直截了当：你向 <code>find</code> 提供搜索路径和待查找文件的一部分信息。可以使用通配符完成模糊搜索；在下面的例子中，星号匹配任何字符，故 <code>find</code> 定位（文件名）以字符 <code>searchterm</code> 结尾的全部文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find /path/to/directory -name &quot;*searchterm&quot;</span></span></code></pre></div><p>默认情况下，<code>find</code> 逐行返回搜索结果，每个结果对应 1 行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~/graphics -name &quot;*jpg&quot;</span></span>
<span class="line"><span>/home/seth/graphics/001.jpg</span></span>
<span class="line"><span>/home/seth/graphics/cat.jpg</span></span>
<span class="line"><span>/home/seth/graphics/penguin.jpg</span></span>
<span class="line"><span>/home/seth/graphics/IMG_0135.jpg</span></span></code></pre></div><p>当使用管道将 <code>find</code> 的结果传递给 <code>parallel</code> 时，每一行中的文件路径被视为 <code>parallel</code> 命令的一个参数。另一方面，如果你需要使用命令处理多个参数，你可以改变队列数据传递给 <code>parallel</code> 的方式。</p><p>下面先给出一个不那么实际的例子，后续会做一些修改使其更加有意义。如果你安装了 GNU Parallel，你可以跟着这个例子操作。</p><p>假设你有 4 个文件，按照每行一个文件的方式列出，具体如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo ada &gt; ada ; echo lovelace &gt; lovelace</span></span>
<span class="line"><span>$ echo richard &gt; richard ; echo stallman &gt; stallman</span></span>
<span class="line"><span>$ ls -1</span></span>
<span class="line"><span>ada</span></span>
<span class="line"><span>lovelace</span></span>
<span class="line"><span>richard</span></span>
<span class="line"><span>stallman</span></span></code></pre></div><p>你需要将两个文件合并成第三个文件，后者同时包含前两个文件的内容。这种情况下，Parallel 需要访问两个文件，使用 <code>-I%</code> 变量的方式不符合本例的预期。</p><p>Parallel 默认情况下读取 1 个队列对象：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1 | parallel echo</span></span>
<span class="line"><span>ada</span></span>
<span class="line"><span>lovelace</span></span>
<span class="line"><span>richard</span></span>
<span class="line"><span>stallman</span></span></code></pre></div><p>现在让 Parallel 每个任务使用 2 个队列对象：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1 | parallel --max-args=2 echo</span></span>
<span class="line"><span>ada lovelace</span></span>
<span class="line"><span>richard stallman</span></span></code></pre></div><p>现在，我们看到行已经并合并；具体而言，<code>ls -1</code> 的两个查询结果会被同时传送给 Parallel。传送给 Parallel 的参数涉及了任务所需的 2 个文件，但目前还只是 1 个有效参数：（对于两个任务分别为）“ada lovelace” 和 “richard stallman”。你真正需要的是每个任务对应 2 个独立的参数。</p><p>值得庆幸的是，Parallel 本身提供了上述所需的解析功能。如果你将 <code>--max-args</code> 设置为 <code>2</code>，那么 <code>{1}</code> 和 <code>{2}</code> 这两个变量分别代表传入参数的第一和第二部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1 | parallel --max-args=2 cat {1} {2} &quot;&gt;&quot; {1}_{2}.person</span></span></code></pre></div><p>在上面的命令中，变量 <code>{1}</code> 值为 <code>ada</code> 或 <code>richard</code> （取决于你选取的任务），变量 <code>{2}</code> 值为 <code>lovelace</code> 或 <code>stallman</code>。通过使用重定向符号（放到引号中，防止被 Bash 识别，以便 Parallel 使用），（两个）文件的内容被分别重定向至新文件 <code>ada_lovelace.person</code> 和 <code>richard_stallman.person</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1</span></span>
<span class="line"><span>ada</span></span>
<span class="line"><span>ada_lovelace.person</span></span>
<span class="line"><span>lovelace</span></span>
<span class="line"><span>richard</span></span>
<span class="line"><span>richard_stallman.person</span></span>
<span class="line"><span>stallman</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat ada_*person</span></span>
<span class="line"><span>ada lovelace</span></span>
<span class="line"><span>$ cat ri*person</span></span>
<span class="line"><span>richard stallman</span></span></code></pre></div><p>如果你整天处理大量几百 MB 大小的日志文件，那么（上述）并行处理文本的方法对你帮忙很大；否则，上述例子只是个用于上手的示例。</p><p>然而，这种处理方法对于很多文本处理之外的操作也有很大帮助。下面是来自电影产业的真实案例，其中需要将一个目录中的视频文件和（对应的）音频文件进行合并。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1</span></span>
<span class="line"><span>12_LS_establishing-manor.avi</span></span>
<span class="line"><span>12_wildsound.flac</span></span>
<span class="line"><span>14_butler-dialogue-mixed.flac</span></span>
<span class="line"><span>14_MS_butler.avi</span></span>
<span class="line"><span>...略...</span></span></code></pre></div><p>使用同样的方法，使用下面这个简单命令即可并行地合并文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1 | parallel --max-args=2 ffmpeg -i {1} -i {2} -vcodec copy -acodec copy {1}.mkv</span></span></code></pre></div><h3 id="简单粗暴的方式" tabindex="-1">简单粗暴的方式 <a class="header-anchor" href="#简单粗暴的方式" aria-label="Permalink to “简单粗暴的方式”">​</a></h3><p>上述花哨的输入输出处理不一定对所有人的口味。如果你希望更直接一些，可以将一堆命令甩给 Parallel，然后去干些其它事情。</p><p>首先，需要创建一个文本文件，每行包含一个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat jobs2run</span></span>
<span class="line"><span>bzip2 oldstuff.tar</span></span>
<span class="line"><span>oggenc music.flac</span></span>
<span class="line"><span>opusenc ambiance.wav</span></span>
<span class="line"><span>convert bigfile.tiff small.jpeg</span></span>
<span class="line"><span>ffmepg -i foo.avi -v:b 12000k foo.mp4</span></span>
<span class="line"><span>xsltproc --output build/tmp.fo style/dm.xsl src/tmp.xml</span></span>
<span class="line"><span>bzip2 archive.tar</span></span></code></pre></div><p>接着，将文件传递给 Parallel：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parallel --jobs 6 &lt; jobs2run</span></span></code></pre></div><p>现在文件中对应的全部任务都在被 Parallel 执行。如果任务数量超过允许的数目（LCTT 译注：应该是 <code>--jobs</code> 指定的数目或默认值），Parallel 会创建并维护一个队列，直到任务全部完成。</p><h3 id="更多内容" tabindex="-1">更多内容 <a class="header-anchor" href="#更多内容" aria-label="Permalink to “更多内容”">​</a></h3>`,48)),i("p",null,[a[5]||(a[5]=s("GNU Parallel 是个强大而灵活的工具，还有很多很多用例无法在本文中讲述。工具的 man 页面提供很多非常酷的例子可供你参考，包括通过 SSH 远程执行和在 Parallel 命令中使用 Bash 函数等。",-1)),e(l,{href:"https://www.youtube.com/watch?v=OpaiGYxkSuQ&list=PL284C9FF2488BC6D1"},{default:n(()=>[...a[3]||(a[3]=[s("YouTube",-1)])]),_:1}),a[6]||(a[6]=s(" 上甚至有一个系列，包含大量操作演示，让你可以直接从 GNU Parallel 团队学习。GNU Paralle 的主要维护者还发布了官方使用指导手册，可以从 ",-1)),e(l,{href:"http://www.lulu.com/shop/ole-tange/gnu-parallel-2018/paperback/product-23558902.html"},{default:n(()=>[...a[4]||(a[4]=[s("Lulu.com",-1)])]),_:1}),a[7]||(a[7]=s(" 获取。",-1))]),a[25]||(a[25]=i("p",null,"GNU Parallel 有可能改变你完成计算的方式；即使没有，也会至少改变你主机花在计算上的时间。马上上手试试吧！",-1)),a[26]||(a[26]=i("hr",null,null,-1)),i("p",null,[a[9]||(a[9]=s("via: ",-1)),e(l,{href:"https://opensource.com/article/18/5/gnu-parallel"},{default:n(()=>[...a[8]||(a[8]=[s("https://opensource.com/article/18/5/gnu-parallel",-1)])]),_:1})]),i("p",null,[a[14]||(a[14]=s("作者：",-1)),e(l,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[10]||(a[10]=[s("Seth Kenlon",-1)])]),_:1}),a[15]||(a[15]=s(" 选题：",-1)),e(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[11]||(a[11]=[s("lujun9972",-1)])]),_:1}),a[16]||(a[16]=s(" 译者：",-1)),e(l,{href:"https://github.com/pinewall"},{default:n(()=>[...a[12]||(a[12]=[s("pinewall",-1)])]),_:1}),a[17]||(a[17]=s(" 校对：",-1)),e(l,{href:"https://github.com/wxy"},{default:n(()=>[...a[13]||(a[13]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[20]||(a[20]=s("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[18]||(a[18]=[s("LCTT",-1)])]),_:1}),a[21]||(a[21]=s(" 原创编译，",-1)),e(l,{href:"https://linux.cn/"},{default:n(()=>[...a[19]||(a[19]=[s("Linux中国",-1)])]),_:1}),a[22]||(a[22]=s(" 荣誉推出",-1))])])}const P=t(c,[["render",h]]);export{v as __pageData,P as default};
